# Let me check parity patterns for output 6s

O_6s = set([(3,15),(4,13),(4,14),(4,16),(5,12),(5,14),(5,18),(5,20),(6,17),(6,19),(6,21),(7,20),(7,22),(9,5),(9,16),(10,4),(10,6),(10,15),(10,17),(11,14),(11,16),(13,10),(14,9),(14,11)])

# Check (r+c) % 2
print("=== Parity (r+c) % 2 ===")
for r, c in sorted(O_6s):
    print(f"({r},{c}): r+c={r+c}, parity={ (r+c) % 2 }")

# Check r % 2 and c % 2
print("\n=== Modulo patterns ===")
for r in range(15):
    parities = {}
    for c in range(30):
        if (r, c) in O_6s:
            if r % 2 not in parities:
                parities[r % 2] = {}
            if c % 2 not in parities[r % 2]:
                parities[r % 2][c % 2] = 0
            parities[r % 2][c % 2] += 1
    print(f"Row {r} (r%2={r%2}): {parities}")

